cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled 3D convolution for kernel (K, K, 1), stride 1, dilation 1, groups 1.
// The input is treated as N*D independent 2D convolutions over the (H, W) plane,
// because the kernel extent along the last dimension is 1.
// Each block computes a 32x32 output spatial tile for 8 output channels
// of one (n, d) slice, staging the (32+K-1)x(32+K-1) input tile and the
// corresponding weight tile in shared memory via CuTe tensors. Each thread
// register-blocks a 2x2 spatial patch x 8 output channels with the
// (K+1)x(K+1) input patch held in registers (loaded via aligned float2
// shared-memory reads), so every staged value feeds many FMAs.
template <int K>
__global__ void conv3d_kk1_kernel(
    const float* __restrict__ X,
    const float* __restrict__ Wt,
    const float* __restrict__ B,
    float* __restrict__ Y,
    int Cin, int H, int Wd, int D,
    int Cout, int Hout, int Wout, int Dout,
    int padding)
{
  constexpr int TH      = 32;
  constexpr int TW      = 32;
  constexpr int COT     = 8;
  constexpr int STH     = 16;
  constexpr int STW     = 16;
  constexpr int Threads = STH * STW;
  constexpr int IH      = TH + K - 1;
  constexpr int IW      = TW + K - 1;
  constexpr int PK      = K + 1;

  const int tid = threadIdx.x;

  // Global strides for contiguous (N, C, H, W, D) layout
  const int64_t sXn = (int64_t)Cin * H * Wd * D;
  const int64_t sXc = (int64_t)H * Wd * D;
  const int64_t sXh = (int64_t)Wd * D;
  const int64_t sXw = (int64_t)D;

  const int64_t sYn = (int64_t)Cout * Hout * Wout * Dout;
  const int64_t sYc = (int64_t)Hout * Wout * Dout;
  const int64_t sYh = (int64_t)Wout * Dout;
  const int64_t sYw = (int64_t)Dout;

  // Tile coordinates
  const int tiles_x = (Wout + TW - 1) / TW;
  const int tile_y  = blockIdx.x / tiles_x;
  const int tile_x  = blockIdx.x - tile_y * tiles_x;
  const int oh0     = tile_y * TH;
  const int ow0     = tile_x * TW;

  // Slice coordinate: b = n * Dout + d_out
  const int b      = blockIdx.y;
  const int n      = b / Dout;
  const int d_out  = b - n * Dout;
  const int d_in   = d_out - padding;
  const bool d_valid = ((unsigned)d_in < (unsigned)D);

  const int co0 = blockIdx.z * COT;

  const int th = tid / STW;
  const int tw = tid - th * STW;
  const int oh = oh0 + 2 * th;
  const int ow = ow0 + 2 * tw;

  Tensor mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * sYn + d_out),
                          make_shape(Cout, Hout, Wout),
                          make_stride(sYc, sYh, sYw));

  if (!d_valid) {
    // This slice lies entirely in the padding of the kernel-size-1 dimension:
    // the convolution contributes nothing, output is just the bias (or zero).
    #pragma unroll
    for (int dz = 0; dz < 2; ++dz) {
      const int ohh = oh + dz;
      if (ohh >= Hout) continue;
      #pragma unroll
      for (int dx = 0; dx < 2; ++dx) {
        const int oww = ow + dx;
        if (oww >= Wout) continue;
        #pragma unroll
        for (int co = 0; co < COT; ++co) {
          const int co_g = co0 + co;
          if (co_g < Cout) {
            mY(co_g, ohh, oww) = (B != nullptr) ? B[co_g] : 0.f;
          }
        }
      }
    }
    return;
  }
  }

  Tensor mX = make_tensor(make_gmem_ptr(X + (int64_t)n * sXn + d_in),
                          make_shape(Cin, H, Wd),
                          make_stride(sXc, sXh, sXw));
  Tensor mW = make_tensor(make_gmem_ptr(Wt),
                          make_shape(Cout, Cin, Int<K>{}, Int<K>{}),
                          make_stride((int64_t)Cin * (K * K), Int<K * K>{}, Int<K>{}, Int<1>{}));

  // Dynamic shared memory: input tile followed by weight tile
  extern __shared__ float4 smem_v[];
  float* sX_ptr = reinterpret_cast<float*>(smem_v);
  float* sW_ptr = sX_ptr + (size_t)Cin * IH * IW;

  Tensor sX = make_tensor(make_smem_ptr(sX_ptr),
                          make_shape(Cin, Int<IH>{}, Int<IW>{}),
                          make_stride(Int<IH * IW>{}, Int<IW>{}, Int<1>{}));
  Tensor sW = make_tensor(make_smem_ptr(sW_ptr),
                          make_shape(Int<COT>{}, Cin, Int<K>{}, Int<K>{}),
                          make_stride(Cin * (K * K), Int<K * K>{}, Int<K>{}, Int<1>{}));

  // Stage the input tile cooperatively (zero-filled halo for padding/borders)
  const int sX_total = Cin * IH * IW;
  for (int idx = tid; idx < sX_total; idx += Threads) {
    int iw = idx % IW;
    int ih = (idx / IW) % IH;
    int ci = idx / (IH * IW);
    int gh = oh0 + ih - padding;
    int gw = ow0 + iw - padding;
    float v = 0.f;
    if ((unsigned)gh < (unsigned)H && (unsigned)gw < (unsigned)Wd) {
      v = mX(ci, gh, gw);
    }
    sX(ci, ih, iw) = v;
  }

  // Stage the weight tile cooperatively
  const int sW_total = COT * Cin * K * K;
  for (int idx = tid; idx < sW_total; idx += Threads) {
    int kw = idx % K;
    int kh = (idx / K) % K;
    int ci = (idx / (K * K)) % Cin;
    int co = idx / (K * K * Cin);
    int co_g = co0 + co;
    float v = 0.f;
    if (co_g < Cout) v = mW(co_g, ci, kh, kw);
    sW(co, ci, kh, kw) = v;
  }
  __syncthreads();

  // Register blocking: each thread accumulates a 2x2 spatial patch for COT
  // output channels, keeping the (K+1)x(K+1) input patch in registers so
  // that every shared-memory input/weight value feeds 2x2xCOT FMAs.
  float acc[2][2][COT];
  #pragma unroll
  for (int dz = 0; dz < 2; ++dz) {
    #pragma unroll
    for (int dx = 0; dx < 2; ++dx) {
      #pragma unroll
      for (int co = 0; co < COT; ++co) {
        const int co_g = co0 + co;
        acc[dz][dx][co] = (B != nullptr && co_g < Cout) ? B[co_g] : 0.f;
      }
    }
  }
  // IW is always even (TW even, K odd), so this base offset is even and
  // 8-byte aligned, allowing aligned float2 shared-memory loads.
  const float* sX_base = sX_ptr + (size_t)2 * (th * IW + tw);
  for (int ci = 0; ci < Cin; ++ci) {
    float patch[PK][PK];
    #pragma unroll
    for (int ph = 0; ph < PK; ++ph) {
      const float2* row2 = reinterpret_cast<const float2*>(sX_base + (size_t)ci * (IH * IW) + ph * IW);
      #pragma unroll
      for (int pv = 0; pv < PK / 2; ++pv) {
        const float2 v = row2[pv];
        patch[ph][2 * pv]     = v.x;
        patch[ph][2 * pv + 1] = v.y;
      }
    }
    #pragma unroll
    for (int kh = 0; kh < K; ++kh) {
      #pragma unroll
      for (int kw = 0; kw < K; ++kw) {
        #pragma unroll
        for (int co = 0; co < COT; ++co) {
          const float wv = sW(co, ci, kh, kw);
          acc[0][0][co] = fmaf(patch[kh][kw],         wv, acc[0][0][co]);
          acc[0][1][co] = fmaf(patch[kh][kw + 1],     wv, acc[0][1][co]);
          acc[1][0][co] = fmaf(patch[kh + 1][kw],     wv, acc[1][0][co]);
          acc[1][1][co] = fmaf(patch[kh + 1][kw + 1], wv, acc[1][1][co]);
        }
      }
    }
  }
  #pragma unroll
  for (int dz = 0; dz < 2; ++dz) {
    const int ohh = oh + dz;
    if (ohh >= Hout) continue;
    #pragma unroll
    for (int dx = 0; dx < 2; ++dx) {
      const int oww = ow + dx;
      if (oww >= Wout) continue;
      #pragma unroll
      for (int co = 0; co < COT; ++co) {
        const int co_g = co0 + co;
        if (co_g < Cout) mY(co_g, ohh, oww) = acc[dz][dx][co];
      }
    }
  }
}

namespace {

template <int K>
void launch_conv3d_kk1(const float* X, const float* Wt, const float* B, float* Y,
                       int N, int Cin, int H, int Wd, int D,
                       int Cout, int Hout, int Wout, int Dout,
                       int padding, cudaStream_t stream)
{
  constexpr int TH  = 32;
  constexpr int TW  = 32;
  constexpr int COT = 8;
  constexpr int IH  = TH + K - 1;
  constexpr int IW  = TW + K - 1;

  const int tiles_x = (Wout + TW - 1) / TW;
  const int tiles_y = (Hout + TH - 1) / TH;

  dim3 block(256);
  dim3 grid(tiles_x * tiles_y, N * Dout, (Cout + COT - 1) / COT);

  size_t smem = ((size_t)Cin * IH * IW + (size_t)COT * Cin * K * K) * sizeof(float);
